/**
 * Verification record for the PGCB monthly archive.
 *
 * Every headline figure is read twice from PGCB's own report — once by fixed
 * column position, once by searching for the item's label — and the two
 * readings compared. Generated by `scratch/build_pgcb_monthly_verification.py`
 * from the report dumps on W:, which is why it is checked in rather than
 * computed at runtime: the sources are not on the web server.
 */
export interface MonthlyStaleRow {
  month: string;
  field: 'max_evening_peak_gen' | 'max_evening_peak_demand';
  value: number;
  /** The month PGCB's own date stamp puts the figure in. */
  occurred: string;
}

export const PGCB_MONTHLY_VERIFICATION = {
  monthsInArchive: 159,
  monthsWithLocalSource: 124,
  figuresCompared: 247,
  figuresAgreed: 247,
  figuresDisagreed: 0,
} as const;

/**
 * Months where PGCB dated a headline figure to an earlier month — the row was
 * not refreshed for that report. The number is genuinely what PGCB published,
 * so it stays P, but it does not describe the month it is printed under.
 */
export const PGCB_MONTHLY_STALE_ROWS: MonthlyStaleRow[] = [
  { month: '2019-05', field: 'max_evening_peak_demand', value: 12893, occurred: '2019-04' },
  { month: '2023-07', field: 'max_evening_peak_gen', value: 14655, occurred: '2023-06' },
  { month: '2024-06', field: 'max_evening_peak_gen', value: 16067, occurred: '2024-05' },
  { month: '2024-10', field: 'max_evening_peak_gen', value: 15717, occurred: '2024-09' },
  { month: '2025-02', field: 'max_evening_peak_gen', value: 11385.54, occurred: '2025-01' },
  { month: '2025-03', field: 'max_evening_peak_gen', value: 11385.54, occurred: '2025-01' },
  { month: '2025-05', field: 'max_evening_peak_gen', value: 16365.8, occurred: '2025-04' },
  { month: '2025-06', field: 'max_evening_peak_gen', value: 16365.8, occurred: '2025-04' },
  { month: '2025-12', field: 'max_evening_peak_gen', value: 15644.99, occurred: '2025-10' },
];

export function staleRowsFor(monthKey: string): MonthlyStaleRow[] {
  return PGCB_MONTHLY_STALE_ROWS.filter((r) => r.month === monthKey);
}

const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
  'August', 'September', 'October', 'November', 'December'];

export function monthLabel(key: string): string {
  const [y, m] = key.split('-').map(Number);
  return `${MONTH_NAMES[m - 1]} ${y}`;
}
